#include <algorithm>
#include <cassert>
#include <cmath>
#include <cstdio>
int main() {
    // Cover the complete uploaded byte image, including all packed lanes,
    // row boundaries, CRAM, and sub-byte positions generated by rotation.
    for(unsigned a=0;a<0x81000;++a)for(unsigned fraction=0;fraction<8;++fraction) {
        float address=float(a)+float(fraction)/8;
        float packed=std::floor(address*.25f);
        float lane=address-packed*4;
        unsigned oldLane=lane<.5f?0:lane<1.5f?1:lane<2.5f?2:3;
        unsigned expected=unsigned(packed)*4+oldLane;
        float newLane=std::min(3.f,std::floor(address-packed*4+.5f));
        float byte=packed*4+newLane;
        float row=std::floor(byte/2048.f);
        float x=byte-row*2048;
        assert(unsigned(row)*2048+unsigned(x)==expected);
        // Point sampling at the centers must select that exact byte texel.
        float u=(x+.5f)/2048.f,v=(row+.5f)/258.f;
        assert(unsigned(std::floor(u*2048))==unsigned(x));
        assert(unsigned(std::floor(v*258))==unsigned(row));
    }
    std::puts("PASS RBG byte view matches packed byte lane and row addressing");
}
